import numpy as np
arr=np.array(inp)
out=arr.copy()
for r in range(arr.shape[0]):
    pos=np.flatnonzero(arr[r]==2)
    for a,b in zip(pos,pos[1:]):
        out[r,a+1:b]=3
for c in range(arr.shape[1]):
    pos=np.flatnonzero(arr[:,c]==2)
    for a,b in zip(pos,pos[1:]):
        out[a+1:b,c]=3
print('\n'.join(' '.join(map(str,row)) for row in out))
print('colored',np.sum(out==3))
